import type { ReactNode } from 'react';

export interface BadgeProps {
  label: string;
  count?: number;
  icon?: ReactNode;
}

export function Badge({ label, count, icon }: BadgeProps) {
  const shown = count ?? 0;
  return (
    <span className="badge">
      {icon ?? <i className="dot" />}
      {label || 'untitled'}
      {shown > 0 && <b>{shown > 99 ? '99+' : shown}</b>}
      {shown < 0 ? <em>invalid</em> : null}
    </span>
  );
}
